\begin{itemchoice}
			\itemch Ta có $2\vec{a} = (6;-2)$ và $3\vec{c} = (0;-6)$. Khi đó $2\vec{a} - \vec{b} - 3\vec{c} = (6 - 2 - 0; -2 - 2 - (-6)) = (4; 2)$.
			\itemch Ta có $\vec{e} = (-3;1) = -1 \cdot (3;-1) = -1\vec{a}$. Vì hệ số $k = -1 < 0$ nên $\vec{e}$ cùng phương và ngược hướng với $\vec{a}$.
			\itemch Ta có $\vec{f} = (1;1) = \dfrac{1}{2}(2;2) = \dfrac{1}{2}\vec{b}$. Vì hệ số $k = \dfrac{1}{2} > 0$ nên $\vec{f}$ cùng phương và cùng hướng với $\vec{b}$.
			\itemch Ta có $\vec{b} - \dfrac{3}{2}\vec{c} = (2; 2) - \left(0; -3\right) = (2; 5)$. Kết quả này khác với tọa độ của $\vec{a} = (3;-1)$.
		\end{itemchoice}
